"""Rows for the tests: valid values for every column, and the rows they point to."""

from typing import Any

from app.entities.note import Note
from app.entities.user import User
from app.unit_of_work import UnitOfWork


def new_user(n: int = 1, **values: Any) -> User:
    """A valid User that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"id": n, "email": f"email-{n}"}
    return User(**(defaults | values))


async def add_user(uow: UnitOfWork, n: int = 1) -> User:
    """A stored User."""
    return await uow.users.insert(new_user(n))


def new_note(n: int = 1, **values: Any) -> Note:
    """A valid Note that is not stored yet; `n` makes its unique values differ, `values` replace any of them."""
    defaults: dict[str, Any] = {"id": n, "text": f"text-{n}"}
    return Note(**(defaults | values))


async def add_note(uow: UnitOfWork, n: int = 1) -> Note:
    """A stored Note, with the rows it points to."""
    parent_0 = await add_user(uow, n)
    return await uow.notes.insert(new_note(n, author_id=parent_0.id))
